#[derive(Debug, Clone, Copy)]
pub enum ClientRole {}

impl crate::Role for ClientRole {
    type Incoming = ClientMessage;
    type Outgoing = ServiceMessage;
    const NAME: &'static str = "M_Device::Client";

    fn vtable() -> &'static onboardapi_sys::obapi_vtable {
        // SAFETY: the vtable is an immutable static defined by the C++ shim.
        unsafe { &*(&raw const onboardapi_sys::obapi_Device_client_vtable) }
    }
}

impl crate::ClientSide for ClientRole {}

/// `M_Device::Client`: receives [`ClientMessage`], sends [`ServiceMessage`].
pub type Client = crate::Endpoint<ClientRole>;

/// Typed senders, one per outgoing operation. They encode straight from borrowed data.
impl crate::Endpoint<ClientRole> {
    /// Command to check if device service is alive.
    /// Note: If the service is not available, then an exception will be thrown.
    pub fn cmd_is_device_alive(&self) -> crate::Result<()> {
        let w = Writer::default();
        self.send_raw(0, w.as_bytes())
    }

    /// Enable or disable the device, i.e. power on and establish connection.
    pub fn cmd_enable_device(&self, is_enabled: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        is_enabled.encode(&mut w);
        self.send_raw(1, w.as_bytes())
    }

    /// Shut down the device, i.e. power off and disconnect.
    pub fn cmd_shutdown_device(&self) -> crate::Result<()> {
        let w = Writer::default();
        self.send_raw(2, w.as_bytes())
    }

    /// Restart the device.
    pub fn cmd_restart_device(&self) -> crate::Result<()> {
        let w = Writer::default();
        self.send_raw(3, w.as_bytes())
    }

    /// Set the mode of the device.
    /// This instructs the device (software) to assume a specific state/mode beyond powering on.
    pub fn cmd_set_device_mode(&self, mode: &crate::common::OperationModeType) -> crate::Result<()> {
        let mut w = Writer::default();
        mode.encode(&mut w);
        self.send_raw(4, w.as_bytes())
    }

    /// Set a specified value.
    pub fn cmd_set_value(&self, id: &str, value: &crate::common::PropertyType) -> crate::Result<()> {
        let mut w = Writer::default();
        id.encode(&mut w);
        value.encode(&mut w);
        self.send_raw(5, w.as_bytes())
    }

    /// Incrementally change a specified value.
    pub fn cmd_set_value_incrementally(&self, id: &str, value: &crate::common::PropertyType) -> crate::Result<()> {
        let mut w = Writer::default();
        id.encode(&mut w);
        value.encode(&mut w);
        self.send_raw(6, w.as_bytes())
    }

    /// Instruct the service to provide the requesting client with a specified value.
    pub fn request_value(&self, id: &str) -> crate::Result<()> {
        let mut w = Writer::default();
        id.encode(&mut w);
        self.send_raw(7, w.as_bytes())
    }

}

